/// Parses the compact path data (absolute M / L / C / Z commands only).
Path _parse(String data) {
  final path = Path();
  final tokens = data.split(RegExp(r'\s+')).where((t) => t.isNotEmpty).toList();
  var i = 0;
  double next() => double.parse(tokens[i++]);
  while (i < tokens.length) {
    final cmd = tokens[i++];
    switch (cmd) {
      case 'M':
        path.moveTo(next(), next());
      case 'L':
        path.lineTo(next(), next());
      case 'C':
        path.cubicTo(next(), next(), next(), next(), next(), next());
      case 'Z':
        path.close();
    }
  }
  return path;
}

/// Ready-to-paint paths. Built once, on first use.
final Path outerArch = _parse(_outerData);
final Path middleArch = _parse(_middleData);
final Path innerArch = _parse(_innerData);
final Path arabicName = _parse(_arabicNameData);
final Path englishName = _parse(_englishNameData);
